// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../QuantAMMStorage.sol";

contract EchidnaStoragePack is
    ScalarQuantAMMBaseStorage,
    ScalarRuleQuantAMMStorage,
    VectorRuleQuantAMMStorage
{
    int256[] internal mockQuantAMMMatrix;
    int256[][] internal matrixResult;

    function r_packUnpack32Array(int256[] memory sourceArray) external pure {
        require(sourceArray.length % 8 == 0);
        for (uint256 i; i < sourceArray.length; i++) {
            sourceArray[i] = sourceArray[i] * 1e9;
        }
        uint256 len = sourceArray.length;
        int256[] memory targetArray = quantAMMPack32Array(sourceArray);
        int256[] memory initial = quantAMMUnpack32Array(targetArray, len);
        for (uint256 i; i < sourceArray.length; i++) {
            assert(sourceArray[i] == initial[i]);
        }
    }

    function r_packUnpack128Array(int256[] memory sourceArray) external pure {
        require(sourceArray.length % 2 == 0);
        uint256 len = sourceArray.length;
        int256[] memory targetArray = _quantAMMPack128Array(sourceArray);
        int256[] memory initial = _quantAMMUnpack128Array(targetArray, len);
        for (uint256 i; i < sourceArray.length; i++) {
            assert(sourceArray[i] == initial[i]);
        }
    }

    function r_packUnpack128Matrix(int256[][] memory sourceMatrix) external {
        uint storageLength;
        if ((sourceMatrix.length * sourceMatrix.length) % 2 == 0) {
            storageLength = (sourceMatrix.length * sourceMatrix.length) / 2;
        } else {
            storageLength =
                ((sourceMatrix.length * sourceMatrix.length) - 1) /
                2;
            ++storageLength;
        }
        require(sourceMatrix.length >= 2);
        for (uint256 i = 0; i < sourceMatrix.length; i++) {
            require(sourceMatrix[i].length >= 2);
        }
        for (uint256 i = 0; i < sourceMatrix.length; i++) {
            for (uint256 j = 0; j < sourceMatrix[i].length; j++) {
                require(sourceMatrix[i][j] < type(int32).max);
            }
        }

        mockQuantAMMMatrix = new int256[](storageLength);
        _quantAMMPack128Matrix(sourceMatrix, mockQuantAMMMatrix);
        matrixResult = _quantAMMUnpack128Matrix(mockQuantAMMMatrix, sourceMatrix.length);

        for (uint256 i = 0; i < sourceMatrix.length; i++) {
            for (uint256 j = 0; j < sourceMatrix[i].length; j++) {
                require(sourceMatrix[i][j] < type(int32).max);
                assert(sourceMatrix[i][j] == matrixResult[i][j]);
            }
        }
    }
}

contracts/echidna/echidna_update_weight_.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../rules/base/QuantammMathGuard.sol";

contract EchidnaQuantAMMMathGuard is QuantAMMMathGuard {
    int256[] public weights;

    constructor() {}

    function weight_update_two_tokens(
        uint8 weightDeltaDivisor,
        uint8 epsilonMaxDivisor
    ) public {
        weights = new int256[](2);
        weights[0] = 1e18 / 2;
        weights[1] = 1e18 / 2;
        int256 epsilonMax = int256(uint256(1e18 / epsilonMaxDivisor));
        int256 absoluteWeightChangeGuardRail = int256(uint256(1e18 / epsilonMaxDivisor));
        int256[] memory newWeights = new int256[](2);
        newWeights[0] = weights[0] - int256(uint256(1e18 / weightDeltaDivisor));
        newWeights[1] = weights[1] + int256(uint256(1e18 / weightDeltaDivisor));
        newWeights = _clampWeights(newWeights, absoluteWeightChangeGuardRail);
        newWeights = _normalizeWeightUpdates(weights, newWeights, epsilonMax);
        weights = newWeights;
    }

    function weight_update_multiple_tokens(
        uint8 numWeights,
        uint8 weightDeltaDivisor,
        uint8 epsilonMaxDivisor
    ) public {
        require(numWeights > 1);
        weights = new int256[](numWeights);
        int256 weightSum;
        for (uint i; i < numWeights - 1; ++i) {
            weights[i] = int256(uint256(1e18 / numWeights));
            weightSum += weights[i];
        }
        weights[weights.length - 1] = 1e18 - weightSum;
        int256 epsilonMax = int256(uint256(1e18 / epsilonMaxDivisor));
        int256 absoluteWeightChangeGuardRail = int256(uint256(1e18 / epsilonMaxDivisor));
        int256[] memory newWeights = new int256[](numWeights);
        uint256 numToUpdate = numWeights;
        if (numWeights % 2 == 1) numToUpdate -= 1;
        for (uint i; i < numWeights; ++i) {
            int256 delta = int256(uint256(1e18 / weightDeltaDivisor));
            if (i % 2 == 1) delta = -delta;
            newWeights[i] = weights[i] + delta;
        }
        newWeights = _clampWeights(newWeights, absoluteWeightChangeGuardRail);
        newWeights = _normalizeWeightUpdates(weights, newWeights, epsilonMax);
        weights = newWeights;
    }

    function echidna_check_weights() public view returns (bool) {
        if (weights.length == 0) return true;
        uint256 weightSum;
        bool allPositive = true;
        bool allInBoundaries = true;
        int256 lowerBound = int256((1e18 / 2) * weights.length);
        int256 upperBound = int256(1e18 - lowerBound);
        for (uint i; i < weights.length; ++i) {
            if (weights[i] < 0) allPositive = false;
            if (weights[i] < lowerBound || weights[i] > upperBound)
                allInBoundaries = false;
            weightSum += uint256(weights[i]);
        }
        return allPositive && weightSum == 1e18;
    }
}

contracts/mock/MockCalculationRule.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity >=0.8.24;

import "@balancer-labs/v3-interfaces/contracts/pool-quantamm/IUpdateRule.sol";
import "../rules/base/QuantammBasedRuleHelpers.sol";
import "../rules/base/QuantammCovarianceBasedRule.sol";
import "../rules/base/QuantammGradientBasedRule.sol";
import "../rules/base/QuantammVarianceBasedRule.sol";

contract MockCalculationRule is
    IUpdateRule,
    QuantAMMCovarianceBasedRule,
    QuantAMMGradientBasedRule,
    QuantAMMVarianceBasedRule
{
    int256[] prevMovingAverage;
    int256[] results;
    int256[][] matrixResults;

    function setPrevMovingAverage(int256[] memory _prevMovingAverage) external {
        prevMovingAverage = _prevMovingAverage;
    }

    function getResults() external view returns (int256[] memory) {
        return results;
    }

    function getMatrixResults() external view returns (int256[][] memory) {
        return matrixResults;
    }

    function convert256Array(int256[] memory originalArray) internal pure returns (int128[] memory) {
        int128[] memory finalArray = new int128[](originalArray.length);
        for (uint i; i < originalArray.length; ++i) {
            finalArray[i] = int128(originalArray[i]);
        }
        return finalArray;
    }

    function externalCalculateQuantAMMVariance(
        int256[] calldata _newData,
        int256[] memory _movingAverage,
        address pool,
        int128[] memory _lambda,
        uint numAssets
    ) external {
        QuantAMMPoolParameters memory poolParameters;
        poolParameters.pool = pool;
        poolParameters.numberOfAssets = numAssets;
        poolParameters.lambda = _lambda;
        poolParameters.movingAverage = _movingAverage;

        results = convert256Array(_calculateQuantAMMVariance(_newData, poolParameters));
    }

    function externalCalculateQuantAMMGradient(
        int256[] calldata _newData,
        int256[] memory _movingAverage,
        address pool,
        int128[] memory lambda,
        uint numAssets
    ) external {
        QuantAMMPoolParameters memory poolParameters;
        poolParameters.pool = pool;
        poolParameters.numberOfAssets = numAssets;
        poolParameters.lambda = lambda;
        poolParameters.movingAverage = _movingAverage;

        int256[] memory calcResults = _calculateQuantAMMGradient(_newData, poolParameters);

        results = calcResults;
    }

    function externalCalculateQuantAMMCovariance(
        int256[] calldata _newData,
        int256[] memory _movingAverage,
        address pool,
        int128[] memory _lambda,
        uint numAssets
    ) external {
        QuantAMMPoolParameters memory poolParameters;
        poolParameters.pool = pool;
        poolParameters.numberOfAssets = numAssets;
        poolParameters.lambda = _lambda;
        poolParameters.movingAverage = _movingAverage;

        matrixResults = _calculateQuantAMMCovariance(_newData, poolParameters);
    }

    function setInitialGradient(address poolAddress, int256[] memory _initialValues, uint _numberOfAssets) external {
        _setGradient(poolAddress, _initialValues, _numberOfAssets);
    }

    function getInitialGradient(address poolAddress, uint256 numAssets) external view returns (int256[] memory) {
        return _quantAMMUnpack128Array(intermediateGradientStates[poolAddress], numAssets);
    }

    function setInitialVariance(address poolAddress, int256[] memory _initialValues, uint _numberOfAssets) external {
        _setIntermediateVariance(poolAddress, _initialValues, _numberOfAssets);
    }

    function getIntermediateVariance(address poolAddress, uint _numberOfAssets) external view returns (int256[] memory) {
        return _quantAMMUnpack128Array(intermediateVarianceStates[poolAddress], _numberOfAssets);
    }

    function setInitialCovariance(
        address poolAddress,
        int256[][] memory _initialValues,
        uint _numberOfAssets
    ) external {
        _setIntermediateCovariance(poolAddress, _initialValues, _numberOfAssets);
    }

    function getIntermediateCovariance(address poolAddress, uint _numberOfAssets) external view returns (int256[][] memory) {
        return _quantAMMUnpack128Matrix(intermediateCovarianceStates[poolAddress], _numberOfAssets);
    }

    function CalculateNewWeights(
        int256[] calldata prevWeights,
        int256[] calldata data,
        address pool,
        int256[][] calldata _parameters,
        uint64[] calldata lambdaStore,
        uint64 epsilonMax,
        uint64 absoluteWeightGuardRail
    ) external override returns (int256[] memory updatedWeights) {}

    function initialisePoolRuleIntermediateValues(
        address poolAddress,
        int256[] memory _newMovingAverages,
        int256[] memory _newParameters,
        uint _numberOfAssets
    ) external override {}

    /// @notice Check if the given parameters are valid for the rule
    function validParameters(int256[][] calldata parameters) external pure override returns (bool) {}
}

