// SPDX-License-Identifier: BUSL-1.1
pragma solidity >=0.8.24;

import "@prb/math/contracts/PRBMathSD59x18.sol";

/// @title QuantAMMMathGuard contract to implement guard rails for QuantAMM weights updates
/// @notice This contract implements the guard rails for QuantAMM weights updates as described in the QuantAMM whitepaper.
abstract contract QuantAMMMathGuard {
    using PRBMathSD59x18 for int256;

    int256 private constant ONE = 1 * 1e18; // Result of PRBMathSD59x18.fromInt(1), store as constant to avoid recalculation every time
    int256 private constant TWO = 2 * 1e18;

    /// @notice Guards QuantAMM weights updates
    /// @param _weights Raw weights to be guarded and normalized
    /// @param _prevWeights Previous weights to be used for normalization
    /// @param _epsilonMax  Maximum allowed change in weights per update step (epsilon) in the QuantAMM whitepaper
    /// @param _absoluteWeightGuardRail Minimum allowed weight in the QuantAMM whitepaper
    function _guardQuantAMMWeights(
        int256[] memory _weights,
        int256[] calldata _prevWeights,
        int256 _epsilonMax,
        int256 _absoluteWeightGuardRail
    ) internal pure returns (int256[] memory guardedNewWeights) {
        // first see if the weights go beyond the maximum/minimum weights
        _weights = _clampWeights(_weights, _absoluteWeightGuardRail);

        //then reduce even further if the weight change is beyond the allowed "speed limit" that protects the changes from front running
        guardedNewWeights = _normalizeWeightUpdates(_prevWeights, _weights, _epsilonMax);
    }

    /// @dev there are some edge cases where the clamping might result to break the guard rail. This is known and the last interpolation block logic in the update weight runner is an ultimate guard against this.
    /// @notice Applies guard rails (min value, max value) to weights and returns the normalized weights
    /// @param _weights Raw weights
    /// @return Clamped weights
    function _clampWeights(
        int256[] memory _weights,
        int256 _absoluteWeightGuardRail
    ) internal pure returns (int256[] memory) {
        unchecked {
            uint weightLength = _weights.length;
            if (weightLength == 1) {
                return _weights;
            }
            int256 absoluteMin = _absoluteWeightGuardRail;
            int256 absoluteMax = ONE -
                (PRBMathSD59x18.fromInt(int256(_weights.length - 1)).mul(_absoluteWeightGuardRail));
            int256 sumRemainerWeight = ONE;
            int256 sumOtherWeights;

            for (uint i; i < weightLength; ++i) {
                if (_weights[i] < absoluteMin) {
                    _weights[i] = absoluteMin;
                    sumRemainerWeight -= absoluteMin;
                } else if (_weights[i] > absoluteMax) {
                    _weights[i] = absoluteMax;
                    sumOtherWeights += absoluteMax;
                }
                else{
                    //CODEHAWKS M-14
                    sumOtherWeights += _weights[i];
                }
            }
            if (sumOtherWeights != 0) {
                int256 proportionalRemainder = sumRemainerWeight.div(sumOtherWeights);
                for (uint i; i < weightLength; ++i) {
                    if (_weights[i] != absoluteMin) {
                        _weights[i] = _weights[i].mul(proportionalRemainder);
                    }
                }
            }
        }
        return _weights;
    }

    ///@notice Normalizes the weights to ensure that the sum of the weights is equal to 1
    ///@param _prevWeights Previous weights
    ///@param _newWeights New weights
    ///@param _epsilonMax Maximum allowed change in weights per update step (epsilon) in the QuantAMM whitepaper
    function _normalizeWeightUpdates(
        int256[] memory _prevWeights,
        int256[] memory _newWeights,
        int256 _epsilonMax
    ) internal pure returns (int256[] memory) {
        unchecked {
            int256 maxAbsChange = _epsilonMax;
            for (uint i; i < _prevWeights.length; ++i) {
                int256 absChange;
                if (_prevWeights[i] > _newWeights[i]) {
                    absChange = _prevWeights[i] - _newWeights[i];
                } else {
                    absChange = _newWeights[i] - _prevWeights[i];
                }
                if (absChange > maxAbsChange) {
                    maxAbsChange = absChange;
                }
            }
            int256 newWeightsSum;
            uint maxWeightIndex;
            int256 maxWeight;
            uint secondMaxWeightIndex;
            int256 secondMaxWeight;
            if (maxAbsChange > _epsilonMax) {
                int256 rescaleFactor = _epsilonMax.div(maxAbsChange);
                for (uint i; i < _newWeights.length; ++i) {
                    int256 newDelta = (_newWeights[i] - _prevWeights[i]).mul(rescaleFactor);
                    _newWeights[i] = _prevWeights[i] + newDelta;
                    newWeightsSum += _newWeights[i];
                    if (_newWeights[i] > maxWeight) {
                        secondMaxWeight = maxWeight;
                        secondMaxWeightIndex = maxWeightIndex;
                        maxWeight = _newWeights[i];
                        maxWeightIndex = i;
                    } else if (_newWeights[i] > secondMaxWeight) {
                        secondMaxWeight = _newWeights[i];
                        secondMaxWeightIndex = i;
                    }
                }
            } else {
                for (uint i; i < _newWeights.length; ++i) {
                    newWeightsSum += _newWeights[i];
                    if (_newWeights[i] > maxWeight) {
                        secondMaxWeight = maxWeight;
                        secondMaxWeightIndex = maxWeightIndex;
                        maxWeight = _newWeights[i];
                        maxWeightIndex = i;
                    } else if (_newWeights[i] > secondMaxWeight) {
                        secondMaxWeight = _newWeights[i];
                        secondMaxWeightIndex = i;
                    }
                }
            }

            // There might a very small (1e-18) rounding error, add this to the first element.
            // Given how the block multiplier guard stops when the multiplier is not 0, and 
            // a first weight hits the guard rail, if applied solely to the max weight, the 
            // updates will stop at T0.
            // we have to make sure that where the rounding error is added to will not be on 
            // a weight that is already at the max weight. if the rounding error is negative
            // it can be added to the max weight, if it is positive add to the second as only 
            // one weight can be at max, guarenteeing the second is not at abs max weight
            //CODEHAWKS M-17
            if(newWeightsSum != ONE){
                if(newWeightsSum > ONE){
                    _newWeights[maxWeightIndex] = _newWeights[maxWeightIndex] - (newWeightsSum - ONE);
                }else{
                    _newWeights[secondMaxWeightIndex] = _newWeights[secondMaxWeightIndex] + (ONE - newWeightsSum);
                }
            }
        }
        return _newWeights;
    }

    /// @notice Raises SD59x18 number x to an arbitrary SD59x18 number y
    /// @dev Calculates (2^(log2(x)))^y == x^y == 2^(log2(x) * y)
    /// @param _x Base
    /// @param _y Exponent
    /// @return result x^y
    function _pow(int256 _x, int256 _y) internal pure returns (int256 result) {
        if (_y == 0 || (_x == 0 && _y == 0)) {
            return 1 * 1e18;
        }
        if (_x == 0) {
            return 0;
        }

        //Noticed effect of this reorg- 2^(log2(x) * y) - the variable multiplied by exp2() can be a large negative and lib can return 0
        return _y.mul(_x.log2()).exp2();
    }
}

contracts/rules/base/QuantammMathMovingA.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity >=0.8.24;

import "@prb/math/contracts/PRBMathSD59x18.sol";
import "../../QuantAMMStorage.sol";

/// @title QuantAMMMathMovingAverage contract for QuantAMM moving average calculations and storage of moving averages for QuantAMM pools
/// @notice Contains the logic for calculating the moving average of the pool price and storing the moving averages
abstract contract QuantAMMMathMovingAverage is ScalarRuleQuantAMMStorage {
    using PRBMathSD59x18 for int256;

    int256 private constant ONE = 1 * 1e18; // Result of PRBMathSD59x18.fromInt(1), store as constant to avoid recalculation every time

    // this can be just the moving averages per token, or if prev moving average is true then it is [...moving averages, ...prev moving averages]
    mapping(address => int256[]) public movingAverages;

    /// @notice View function to get the moving averages for a given pool
    /// @param poolAddress The address of the pool
    /// @param numberOfAssets The number of assets in the pool
    /// @return The unpacked moving averages as an array of int256
    function getMovingAverages(address poolAddress, uint numberOfAssets) external view returns (int256[] memory) {
        return _quantAMMUnpack128Array(movingAverages[poolAddress], numberOfAssets);
    }

    /// @notice Calculates the new moving average value, i.e. p̅(t) = p̅(t - 1) + (1 - λ)(p(t) - p̅(t - 1))
    /// @param _prevMovingAverage p̅(t - 1)
    /// @param _newData p(t)
    /// @param _lambda λ
    /// @param _numberOfAssets number of assets in the pool
    /// @return p̅(t) avertage price of the pool
    function _calculateQuantAMMMovingAverage(
        int256[] memory _prevMovingAverage,
        int256[] memory _newData,
        int128[] memory _lambda,
        uint _numberOfAssets
    ) internal pure returns (int256[] memory) {
        int256[] memory newMovingAverage = new int256[](_numberOfAssets);
        int256 convertedLambda = int256(_lambda[0]);
        int256 oneMinusLambda = ONE - convertedLambda;
        if (_lambda.length == 1) {
            for (uint i; i < _numberOfAssets; ) {
                // p̅(t) = p̅(t - 1) + (1 - λ)(p(t) - p̅(t - 1)) - see whitepaper
                int256 movingAverageI = _prevMovingAverage[i];
                //CODEHAWKS INFO /s/200 reordering to avoid precision loss
                newMovingAverage[i] = (movingAverageI.mul(convertedLambda) + _newData[i].mul(oneMinusLambda)).div(ONE);
                unchecked {
                    ++i;
                }
            }
        } else {
            for (uint i; i < _numberOfAssets; ) {
                unchecked {
                    convertedLambda = int256(_lambda[i]);
                    oneMinusLambda = ONE - convertedLambda;
                }
                int256 movingAverageI = _prevMovingAverage[i];
                // p̅(t) = p̅(t - 1) + (1 - λ)(p(t) - p̅(t - 1))
                //CODEHAWKS INFO /s/200 reordering to avoid precision loss
                newMovingAverage[i] = (movingAverageI.mul(convertedLambda) + _newData[i].mul(oneMinusLambda)).div(ONE);
                unchecked {
                    ++i;
                }
            }
        }

        return newMovingAverage;
    }

    /// @param _poolAddress address of pool being initialised
    /// @param _initialMovingAverages array of initial moving averages
    /// @param _numberOfAssets number of assets in the pool
    function _setInitialMovingAverages(
        address _poolAddress,
        int256[] memory _initialMovingAverages,
        uint _numberOfAssets
    ) internal {
        //CODEHAWKS H-04 no longer storing prev, also /s/767
        if (_initialMovingAverages.length == _numberOfAssets) {
            //should be during create pool
            movingAverages[_poolAddress] = _quantAMMPack128Array(_initialMovingAverages);
        } else {
            revert("Invalid set moving avg");
        }
    }
}

contracts/rules/base/QuantammVarianceBas.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity >=0.8.24;

import "@prb/math/contracts/PRBMathSD59x18.sol";
import "../../UpdateWeightRunner.sol";
import "../../QuantAMMStorage.sol";
import "./QuantammBasedRuleHelpers.sol";

/// @title QuantAMMVarianceBasedRule contract for QuantAMM variance calculations and storage of variance for QuantAMM pools
/// @notice Contains the logic for calculating the variance of the pool price and storing the variance
contract QuantAMMVarianceBasedRule is ScalarRuleQuantAMMStorage {
    using PRBMathSD59x18 for int256;

    int256 private constant ONE = 1 * 1e18; // Result of PRBMathSD59x18.fromInt(1), store as constant to avoid recalculation every time
    int256 private constant TENPOWEIGHTEEN = (10 ** 18);

    bool private immutable _protectedAccess;

    // Key is the pool address and stores the intermediate variance state in a packed array of 128 bit integers
    mapping(address => int256[]) internal intermediateVarianceStates;

    /// @notice View function to get the intermediate variance state for a given pool
    /// @param poolAddress The address of the pool
    /// @param numberOfAssets The number of assets in the pool
    /// @return The unpacked intermediate variance state as an array of int256
    function getIntermediateVarianceState(
        address poolAddress,
        uint numberOfAssets
    ) external view returns (int256[] memory) {
        return _quantAMMUnpack128Array(intermediateVarianceStates[poolAddress], numberOfAssets);
    }

    /// @dev struct to avoind stack to deep issues
    /// @notice Struct to store local variables for the variance calculation
    /// @param storageIndex index of the storage array
    /// @param secondIndex index of the second intermediate value
    /// @param intermediateState intermediate state during a variance calculation
    /// @param n number of assets in the pool
    /// @param nMinusOne n - 1
    /// @param notDivisibleByTwo boolean to check if n is not divisible by 2
    /// @param convertedLambda λ
    /// @param oneMinusLambda 1 - λ
    /// @param intermediateVarianceState intermediate state of the variance
    /// @param finalState final state of the variance
    struct QuantAMMVarianceLocals {
        uint256 storageIndex;
        uint256 secondIndex;
        int256 intermediateState;
        uint256 n;
        uint256 nMinusOne;
        bool notDivisibleByTwo;
        int256 convertedLambda;
        int256 oneMinusLambda;
        int256[] intermediateVarianceState;
        int256[] finalState;
    }

    /// @notice Calculates the new intermediate state for the variance update, i.e. the diagonal entries of A(t) = λA(t - 1) + (p(t) - p̅(t - 1))(p(t) - p̅(t))'
    /// @notice Calculates the new variances vector given the intermediate state, i.e. the diagonal entries of Σ(t) = (1 - λ)A(t)
    /// @param _newData p(t)
    /// @param _poolParameters _movingAverage p̅(t), _lambda λ, _numberOfAssets number of assets in the pool, _pool the target pool address
    function _calculateQuantAMMVariance(
        int256[] memory _newData,
        QuantAMMPoolParameters memory _poolParameters
    ) internal returns (int256[] memory) {
        QuantAMMVarianceLocals memory locals;
        locals.n = _poolParameters.numberOfAssets;
        locals.finalState = new int256[](locals.n);
        locals.intermediateVarianceState = _quantAMMUnpack128Array(
            intermediateVarianceStates[_poolParameters.pool],
            locals.n
        );
        locals.nMinusOne = locals.n - 1;
        locals.notDivisibleByTwo = locals.n % 2 != 0;
        locals.convertedLambda = int256(_poolParameters.lambda[0]);
        locals.oneMinusLambda = ONE - locals.convertedLambda;

        //the packed int256 slot index to store the intermediate variance state

        if (_poolParameters.lambda.length == 1) {
            //scalar parameters mean the calculation is simplified and even if it increases function and
            //contract size it decrease gas computed given iterative design tests
            if (locals.notDivisibleByTwo) {
                unchecked {
                    --locals.nMinusOne;
                }
            }

            for (uint i; i < locals.nMinusOne; ) {
                // Intermediate states are calculated in pairs to then SSTORE as we go along saving gas from a redundant SSTORE of length if we did the whole array
                // calculating and storing in the same loop also saves loop costs

                locals.intermediateState =
                    locals.convertedLambda.mul(locals.intermediateVarianceState[i]) +
                    (_newData[i] - _poolParameters.movingAverage[locals.n + i])
                        .mul(_newData[i] - _poolParameters.movingAverage[i])
                        .div(TENPOWEIGHTEEN); // p(t) - p̅(t - 1))_i * (p(t) - p̅(t))_i

                locals.intermediateVarianceState[i] = locals.intermediateState;
                locals.finalState[i] = locals.oneMinusLambda.mul(locals.intermediateState);

                unchecked {
                    locals.secondIndex = i + 1;
                }

                locals.intermediateState =
                    locals.convertedLambda.mul(locals.intermediateVarianceState[locals.secondIndex]) +
                    (_newData[locals.secondIndex] - _poolParameters.movingAverage[locals.n + locals.secondIndex])
                        .mul(_newData[locals.secondIndex] - _poolParameters.movingAverage[locals.secondIndex])
                        .div(TENPOWEIGHTEEN); // p(t) - p̅(t - 1))_i * (p(t) - p̅(t))_i

                locals.intermediateVarianceState[locals.secondIndex] = locals.intermediateState;
                intermediateVarianceStates[_poolParameters.pool][locals.storageIndex] = _quantAMMPackTwo128(
                    locals.intermediateVarianceState[i],
                    locals.intermediateVarianceState[locals.secondIndex]
                );

                locals.finalState[locals.secondIndex] = locals.oneMinusLambda.mul(locals.intermediateState);

                unchecked {
                    i += 2;
                    ++locals.storageIndex;
                }
            }

            if (locals.notDivisibleByTwo) {
                unchecked {
                    ++locals.nMinusOne;
                }
                locals.intermediateState =
                    locals.convertedLambda.mul(locals.intermediateVarianceState[locals.nMinusOne]) +
                    (_newData[locals.nMinusOne] - _poolParameters.movingAverage[locals.n + locals.nMinusOne])
                        .mul(_newData[locals.nMinusOne] - _poolParameters.movingAverage[locals.nMinusOne])
                        .div(TENPOWEIGHTEEN); // p(t) - p̅(t - 1))_i * (p(t) - p̅(t))_i

                locals.intermediateVarianceState[locals.nMinusOne] = locals.intermediateState;
                locals.finalState[locals.nMinusOne] = locals.oneMinusLambda.mul(locals.intermediateState);
                intermediateVarianceStates[_poolParameters.pool][locals.storageIndex] = locals
                    .intermediateVarianceState[locals.nMinusOne];
            }
        } else {
            //CODEHAWKS H-01
            if (locals.notDivisibleByTwo) {
                unchecked {
                    --locals.nMinusOne;
                }
            }

            //vector parameter calculation is the same but we have to keep track of and access the right vector parameter
            for (uint i; i < locals.nMinusOne; ) {
                unchecked {
                    locals.convertedLambda = int256(_poolParameters.lambda[i]);
                    locals.oneMinusLambda = ONE - locals.convertedLambda;
                }
                // p(t) - p̅(t - 1))_i * (p(t) - p̅(t))_i
                locals.intermediateState =
                    locals.convertedLambda.mul(locals.intermediateVarianceState[i]) +
                    (_newData[i] - _poolParameters.movingAverage[locals.n + i])
                        .mul(_newData[i] - _poolParameters.movingAverage[i])
                        .div(TENPOWEIGHTEEN);

                locals.intermediateVarianceState[i] = locals.intermediateState;
                locals.finalState[i] = locals.oneMinusLambda.mul(locals.intermediateState);

                unchecked {
                    locals.secondIndex = i + 1;
                    locals.convertedLambda = int256(_poolParameters.lambda[i + 1]);
                    locals.oneMinusLambda = ONE - locals.convertedLambda;
                }
                // p(t) - p̅(t - 1))_i * (p(t) - p̅(t))_i
                locals.intermediateState =
                    locals.convertedLambda.mul(locals.intermediateVarianceState[locals.secondIndex]) +
                    (_newData[locals.secondIndex] - _poolParameters.movingAverage[locals.n + locals.secondIndex])
                        .mul(_newData[locals.secondIndex] - _poolParameters.movingAverage[locals.secondIndex])
                        .div(TENPOWEIGHTEEN);

                locals.intermediateVarianceState[locals.secondIndex] = locals.intermediateState;

                intermediateVarianceStates[_poolParameters.pool][locals.storageIndex] = _quantAMMPackTwo128(
                    locals.intermediateVarianceState[i],
                    locals.intermediateVarianceState[locals.secondIndex]
                );
                locals.finalState[locals.secondIndex] = locals.oneMinusLambda.mul(locals.intermediateState);

                unchecked {
                    i += 2;
                    ++locals.storageIndex;
                }
            }

            if (locals.notDivisibleByTwo) {
                unchecked {
                    ++locals.nMinusOne;

                    locals.convertedLambda = int256(_poolParameters.lambda[locals.nMinusOne]);
                    locals.oneMinusLambda = ONE - locals.convertedLambda;
                }
                locals.intermediateState =
                    locals.convertedLambda.mul(locals.intermediateVarianceState[locals.nMinusOne]) +
                    (_newData[locals.nMinusOne] - _poolParameters.movingAverage[locals.n + locals.nMinusOne])
                        .mul(_newData[locals.nMinusOne] - _poolParameters.movingAverage[locals.nMinusOne])
                        .div(TENPOWEIGHTEEN); // p(t) - p̅(t - 1))_i * (p(t) - p̅(t))_i

                locals.intermediateVarianceState[locals.nMinusOne] = locals.intermediateState;
                locals.finalState[locals.nMinusOne] = locals.oneMinusLambda.mul(locals.intermediateState);

                //CODEHAWKS INFO /s/755
                intermediateVarianceStates[_poolParameters.pool][locals.storageIndex] = _quantAMMPackTwo128(
                    int256(0),
                    locals.intermediateVarianceState[locals.nMinusOne]
                );
            }
        }

        return locals.finalState;
    }

    /// @param _poolAddress the target pool address
    /// @param _initialValues the initial variance values
    /// @param _numberOfAssets the number of assets in the pool
    function _setIntermediateVariance(
        address _poolAddress,
        int256[] memory _initialValues,
        uint _numberOfAssets
    ) internal {
        uint storeLength = intermediateVarianceStates[_poolAddress].length;
        bool evenInitialValues = _initialValues.length % 2 == 0;

        //CODEHAWKS M-18
        if (
            (_initialValues.length == _numberOfAssets) &&
            (storeLength == 0 ||
                (evenInitialValues && _initialValues.length / 2 == storeLength) ||
                (!evenInitialValues && (_initialValues.length + 1) / 2 == storeLength))
        ) {
            //should be during create pool
            intermediateVarianceStates[_poolAddress] = _quantAMMPack128Array(_initialValues);
        } else {
            revert("Invalid set variance");
        }
    }
}

contracts/rules/ChannelFollowingUpdateRu.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity >=0.8.24;

import "@prb/math/contracts/PRBMathSD59x18.sol";
import "./base/QuantammGradientBasedRule.sol";
import "./base/QuantammMathGuard.sol";
import "./base/QuantammMathMovingAverage.sol";
import "./UpdateRule.sol";

/// @title ChannelFollowingUpdateRule contract for QuantAMM channel following weight updates
/// @notice Contains the logic for calculating the new weights of a QuantAMM pool using the channel following strategy
contract ChannelFollowingUpdateRule is QuantAMMGradientBasedRule, UpdateRule {
    constructor(address _updateWeightRunner) UpdateRule(_updateWeightRunner) {
        name = "ChannelFollowing";

        parameterDescriptions = new string[](7);
        parameterDescriptions[0] = "Kappa: Kappa dictates the aggressiveness of response to a signal change.";
        parameterDescriptions[1] = "Width: Width parameter for the mean reversion channel.";
        parameterDescriptions[2] = "Amplitude: Amplitude of the mean reversion effect.";
        parameterDescriptions[3] = "Exponents: Exponents for the trend following portion.";
        parameterDescriptions[4] = "Inverse Scaling: Scaling factor for channel portion. "
            "If set to max(exp(-x^2/2)sin(pi*x/3)) [=0.541519...] "
            "then the amplitude parameter directly controls the channel height.";
        parameterDescriptions[5] = "Pre-exp Scaling: Scaling factor before exponentiation in the trend following portion.";
        parameterDescriptions[6] = "Use raw price: 0 = use moving average, 1 = use raw price for denominator of price gradient.";
    }

    using PRBMathSD59x18 for int256;

    int256 private constant ONE = 1e18;
    int256 private constant TWO = 2e18;
    int256 private constant THREE = 3e18;
    int256 private constant SIX = 6e18;
    int256 private constant PI = 3.141592653589793238e18; // π scaled to 18 decimals
    uint16 private constant REQUIRES_PREV_MAVG = 0;

    /// @dev struct to avoid stack too deep issues
    /// @notice Struct to store local variables for the channel following calculation
    /// @param kappa array of kappa value parameters
    /// @param width array of width value parameters
    /// @param amplitude array of amplitude value parameters
    /// @param exponents array of exponent value parameters
    /// @param inverseScaling array of inverse scaling value parameters
    /// @param preExpScaling array of pre-exp scaling value parameters
    /// @param newWeights array of new weights
    /// @param signal array of signal values
    /// @param normalizationFactor normalization factor for the weights
    /// @param prevWeightLength length of the previous weights
    /// @param useRawPrice boolean to determine if raw price should be used or average
    /// @param i index for looping
    /// @param denominator denominator for the weights
    /// @param sumKappa sum of all kappa values
    struct ChannelFollowingLocals {
        int256[] kappa;
        int256[] width;
        int256[] amplitude;
        int256[] exponents;
        int256[] inverseScaling;
        int256[] preExpScaling;
        int256[] newWeights;
        int256[] signal;
        int256 normalizationFactor;
        uint256 prevWeightLength;
        bool useRawPrice;
        uint i;
        int256 denominator;
        int256 sumKappa;
    }

    /// @notice Calculates the new weights for a QuantAMM pool using the channel following strategy.
    /// @notice The channel following strategy combines trend following with a channel component:
    /// w(t) = w(t-1) + κ[channel + trend - normalizationFactor]
    /// where:
    /// - g = normalized price gradient = (1/p)·(dp/dt)
    /// - envelope = exp(-g²/(2W²))
    /// - s = pi * g / (3W)
    /// - channel = -(A/h)·envelope · (s - 1/6 s^3)
    /// - trend = (1-envelope) * sign(g) * |g/(2S)|^(exponent)
    /// - normalizationFactor = 1/N * ∑(κ[channel + trend])_i
    /// Parameters:
    /// - κ: Kappa controls overall update magnitude
    /// - W: Width controls the channel and envelope width
    /// - A: Amplitude controls channel height
    /// - exponents: Exponent for the trend following portion
    /// - h: Inverse scaling within the channel
    /// - S: Pre-exp scaling for trend component
    /// The strategy aims to:
    /// 1. Mean-revert within the channel (channel component, for small changes in g)
    /// 2. Follow trends (nonlinearly, if exponents are not 1) outside the channel (trend component, for large changes in g)
    /// 3. Smoothly transition between the two regimes (via the envelope function)
    /// @param _prevWeights the previous weights retrieved from the vault
    /// @param _data the latest data, usually price
    /// @param _parameters the parameters of the rule that are not lambda.
    ///     Parameters [0] through [5] are arrays/vectors, [6] is a scalar.
    ///     [0]=kappa
    ///     [1]=width
    ///     [2]=amplitude
    ///     [3]=exponents
    ///     [4]=inverseScaling
    ///     [5]=preExpScaling
    ///     [6]=useRawPrice
    function _getWeights(
        int256[] calldata _prevWeights,
        int256[] memory _data,
        int256[][] calldata _parameters,
        QuantAMMPoolParameters memory _poolParameters
    ) internal override returns (int256[] memory newWeightsConverted) {
        ChannelFollowingLocals memory locals;

        locals.kappa = _parameters[0];
        locals.width = _parameters[1];
        locals.amplitude = _parameters[2];
        locals.exponents = _parameters[3];
        locals.inverseScaling = _parameters[4];
        locals.preExpScaling = _parameters[5];

        _poolParameters.numberOfAssets = _prevWeights.length;
        locals.prevWeightLength = _prevWeights.length;

        // the 7th parameter to determine if momentum should use the price or the average price as the denominator
        // using the average price has shown greater performance and resilience due to greater smoothing
        locals.useRawPrice = _parameters[6][0] == ONE;

        // Calculate price gradients
        locals.newWeights = _calculateQuantAMMGradient(_data, _poolParameters);

        for (locals.i = 0; locals.i < locals.prevWeightLength; ) {
            locals.denominator = _poolParameters.movingAverage[locals.i];
            if (locals.useRawPrice) {
                locals.denominator = _data[locals.i];
            }

            // 1/p(t) * ∂p(t)/∂t calculated and stored as used in multiple places
            locals.newWeights[locals.i] = ONE.div(locals.denominator).mul(locals.newWeights[locals.i]);

            unchecked {
                ++locals.i;
            }
        }
        locals.signal = new int256[](locals.prevWeightLength);

        // Calculate signal for each asset
        for (locals.i = 0; locals.i < locals.prevWeightLength; ) {
            // Calculate envelope: exp(-(price_gradient^2) / (2 * width^2))
            int256 gradientSquared = locals.newWeights[locals.i].mul(locals.newWeights[locals.i]);
            int256 trendPortion;
            int256 channelPortion;
            int256 envelope_exponent;
            int256 envelope;
            if (locals.kappa.length == 1) {
                int256 widthSquared = locals.width[0].mul(locals.width[0]);
                envelope_exponent = -gradientSquared.div(widthSquared.mul(TWO));
                envelope = envelope_exponent.exp();

                // Calculate scaled price gradient: π * price_gradient / (3 * width)
                int256 scaledGradient = PI.mul(locals.newWeights[locals.i]).div(locals.width[0].mul(THREE));

                // Calculate channel portion
                channelPortion = locals
                    .amplitude[0]
                    .mul(envelope)
                    .mul(scaledGradient - scaledGradient.mul(scaledGradient).mul(scaledGradient).div(SIX))
                    .div(locals.inverseScaling[0]);

                // Calculate trend portion
                int256 absGradient = locals.newWeights[locals.i] >= 0
                    ? locals.newWeights[locals.i]
                    : -locals.newWeights[locals.i];

                int256 scaledAbsGradient = absGradient.div(locals.preExpScaling[0].mul(TWO));

                trendPortion = _pow(scaledAbsGradient, locals.exponents[0]);
            } else {
                int256 widthSquared = locals.width[locals.i].mul(locals.width[locals.i]);
                envelope = (-gradientSquared.div(widthSquared.mul(TWO))).exp();
                // Calculate scaled price gradient: π * price_gradient / (3 * width)
                int256 scaledGradient = PI.mul(locals.newWeights[locals.i]).div(locals.width[locals.i].mul(THREE));

                // Calculate channel portion
                channelPortion = locals
                    .amplitude[locals.i]
                    .mul(envelope)
                    .mul(scaledGradient - scaledGradient.mul(scaledGradient).mul(scaledGradient).div(SIX))
                    .div(locals.inverseScaling[locals.i]);

                // Calculate trend portion
                int256 absGradient = locals.newWeights[locals.i] >= 0
                    ? locals.newWeights[locals.i]
                    : -locals.newWeights[locals.i];

                int256 scaledAbsGradient = absGradient.div(locals.preExpScaling[locals.i].mul(TWO));
                trendPortion = _pow(scaledAbsGradient, locals.exponents[locals.i]);
            }
            // We want, in effect, a mean-reverting channel, so we want the channel portion to act as if it were
            // its own anti-momentum strategy (ie if there were no envelope, no trendPortion, we would want this
            // strategy to look like an anti-momentum strategy). Amplitude is required to be positive, so to achieve
            // this we can just negate the channel portion.
            channelPortion = -channelPortion;

            // The trendPortion variable so far has been calculated using the absolute value of the price gradient.
            // This is because x^y is not defined for negative x if y is not an integer. So we need to reintroduce
            // the sign of the price gradient to the trendPortion. We can use the sign of the price gradient to achieve this.
            if (locals.newWeights[locals.i] < 0) {
                trendPortion = -trendPortion;
            }


            trendPortion = trendPortion.mul(ONE - envelope);

            locals.signal[locals.i] = channelPortion + trendPortion;

            if (locals.kappa.length == 1) {
                locals.normalizationFactor += locals.signal[locals.i];
            } else {
                locals.normalizationFactor += locals.signal[locals.i].mul(locals.kappa[locals.i]);
            }

            unchecked {
                ++locals.i;
            }
        }

        newWeightsConverted = new int256[](locals.prevWeightLength);

        // Calculate final weights
        if (locals.kappa.length == 1) {
            locals.normalizationFactor /= int256(locals.prevWeightLength);
            for (locals.i = 0; locals.i < locals.prevWeightLength; ) {
                newWeightsConverted[locals.i] =
                    _prevWeights[locals.i] +
                    locals.kappa[0].mul(locals.signal[locals.i] - locals.normalizationFactor);

                unchecked {
                    ++locals.i;
                }
            }
        } else {
            for (locals.i = 0; locals.i < locals.kappa.length; ) {
                locals.sumKappa += locals.kappa[locals.i];
                unchecked {
                    ++locals.i;
                }
            }

            locals.normalizationFactor = locals.normalizationFactor.div(locals.sumKappa);
            for (locals.i = 0; locals.i < locals.prevWeightLength; ) {
                int256 weightUpdate = locals.kappa[locals.i].mul(locals.signal[locals.i] - locals.normalizationFactor);
                newWeightsConverted[locals.i] = _prevWeights[locals.i] + weightUpdate;

                unchecked {
                    ++locals.i;
                }
            }
        }

        return newWeightsConverted;
    }

    /// @notice Check if the rule requires the previous moving average
    /// @return 0 if it does not require the previous moving average, 1 if it does
    function _requiresPrevMovingAverage() internal pure override returns (uint16) {
        return REQUIRES_PREV_MAVG;
    }

    /// @notice Set the initial intermediate values for the pool, in this case the gradient
    /// @param _poolAddress the target pool address
    /// @param _initialValues the initial values of the pool
    /// @param _numberOfAssets the number of assets in the pool
    function _setInitialIntermediateValues(
        address _poolAddress,
        int256[] memory _initialValues,
        uint _numberOfAssets
    ) internal override {
        _setGradient(_poolAddress, _initialValues, _numberOfAssets);
    }

    function validParameters(int256[][] calldata _parameters) external pure override returns (bool) {
        // Check parameters array length is 7
        if (_parameters.length != 7) return false;
        // All parameter arrays must have same length
        uint baseLength = _parameters[0].length;
        if (baseLength == 0) return false;

        for (uint i = 1; i < 6; i++) {
            if (_parameters[i].length != baseLength) {
                return false;
            }
        }

        // Validate parameter values
        for (uint i = 0; i < baseLength; i++) {
            if (_parameters[0][i] <= 0) return false; // kappa must be positive
            if (_parameters[1][i] <= 0) return false; // width must be positive
            if (_parameters[2][i] <= 0) return false; // amplitude must be positive
            if (_parameters[3][i] <= 0) return false; // exponents must be positive
            if (_parameters[4][i] <= 0) return false; // inverse scaling must be positive
            if (_parameters[5][i] <= 0) return false; // pre-exp scaling must be positive
        }
        // Check parameter 7 is scalar (length 1) and is either 0 or 1
        if (_parameters[6].length != 1) return false;
        if (_parameters[6][0] != 0 && _parameters[6][0] != PRBMathSD59x18.fromInt(1)) return false;

        return true;
    }
}

contracts/rules/DifferenceMomentumUpdate.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity >=0.8.24;

import "@prb/math/contracts/PRBMathSD59x18.sol";
import "./UpdateRule.sol";
import "./base/QuantammGradientBasedRule.sol";

/// @title DifferenceMomentumUpdateRule contract for QuantAMM update rule based on Moving Average Convergence Divergence
/// @notice Contains the logic for calculating the new weights of a QuantAMM pool using the difference momentum update rule
contract DifferenceMomentumUpdateRule is QuantAMMGradientBasedRule, UpdateRule {
    constructor(address _updateWeightRunner) UpdateRule(_updateWeightRunner) {
        name = "DifferenceMomentum";

        parameterDescriptions = new string[](3);
        parameterDescriptions[
            0
        ] = "Kappa: Kappa dictates the aggressiveness of the rule's response to a signal change (here, (EWMA_short - EWMA_long) / EWMA_long)";
        parameterDescriptions[
            1
        ] = "Lambda Short: This Lambda dictates price smoothing for the short-memory moving average";
        parameterDescriptions[
            2
        ] = "Lambda Long: This Lambda dictates price smoothing for the long-memory moving average";
    }

    using PRBMathSD59x18 for int256;

    int256 private constant ONE = 1 * 1e18; // Result of PRBMathSD59x18.fromInt(1), store as constant to avoid recalculation every time
    uint16 private constant REQUIRES_PREV_MAVG = 0;

    mapping(address => int256[]) public shortMovingAverages;

    /// @dev struct to avoid stack too deep issues
    /// @notice Struct to store local variables for the momentum calculation
    /// @param kappaStore array of kappa value parameters
    /// @param newWeights array of new weights
    /// @param normalizationFactor normalization factor for the weights
    /// @param prevWeightLength length of the previous weights
    /// @param i index for looping
    /// @param denominator denominator for the weights
    /// @param sumKappa sum of all kappa values
    /// @param res result of the calculation
    struct QuantAMMDifferenceMomentumLocals {
        int256[] kappaStore;
        int256[] newWeights;
        int256 normalizationFactor;
        uint256 prevWeightLength;
        uint i;
        int256 denominator;
        int256 sumKappa;
        int256 res;
    }

    /// @notice w(t) = w(t − 1) + κ · (  (EWMA_short - EWMA_long) / EWMA_long − ℓp(t)) where ℓp(t) = 1/N * ∑((EWMA_short - EWMA_long) / EWMA_long)_i
    /// @param _prevWeights the previous weights retrieved from the vault
    /// @param _data the latest data from the signal, usually price
    /// @param _parameters The parameters of the rule that are not lambda_long:
    ///                   [0] = kappa: Can be per token (vector) or single for all tokens (scalar)
    ///                   [1] = lambda short: Can be per token (vector) or single for all tokens (scalar)
    function _getWeights(
        int256[] calldata _prevWeights,
        int256[] memory _data,
        int256[][] calldata _parameters,
        QuantAMMPoolParameters memory _poolParameters
    ) internal override returns (int256[] memory newWeightsConverted) {
        QuantAMMDifferenceMomentumLocals memory locals;
        locals.kappaStore = _parameters[0];
        _poolParameters.numberOfAssets = _prevWeights.length;
        int128[] memory lambdaShort = new int128[](_parameters[1].length);
        for (locals.i; locals.i < lambdaShort.length; ) {
            lambdaShort[locals.i] = int128(_parameters[1][locals.i]);
            unchecked {
                ++locals.i;
            }
        }

        int256[] memory currentShortMovingAverages = _quantAMMUnpack128Array(
            shortMovingAverages[_poolParameters.pool],
            _poolParameters.numberOfAssets
        );

        int256[] memory newShortMovingAverages = _calculateQuantAMMMovingAverage(
            currentShortMovingAverages,
            _data,
            lambdaShort,
            _poolParameters.numberOfAssets
        );
        shortMovingAverages[_poolParameters.pool] = _quantAMMPack128Array(newShortMovingAverages);
        //CODEHAWKS INFO /s/325, /s/402, /s/540, /s/944 remove for loop

        locals.prevWeightLength = _prevWeights.length;

        // newWeights is reused multiple times to save gas of multiple array initialisation
        locals.newWeights = new int256[](locals.prevWeightLength);
        for (locals.i = 0; locals.i < locals.prevWeightLength; ) {
            locals.newWeights[locals.i] = newShortMovingAverages[locals.i] - _poolParameters.movingAverage[locals.i];

            locals.denominator = _poolParameters.movingAverage[locals.i];
            // (EWMA_short - EWMA_long) / EWMA_long calculated and stored as used in multiple places
            locals.newWeights[locals.i] = ONE.div(locals.denominator).mul(locals.newWeights[locals.i]);
            if (locals.kappaStore.length == 1) {
                locals.normalizationFactor += locals.newWeights[locals.i];
            } else {
                locals.normalizationFactor += (locals.newWeights[locals.i].mul(locals.kappaStore[locals.i]));
            }

            unchecked {
                ++locals.i;
            }
        }
        newWeightsConverted = new int256[](locals.prevWeightLength);

        if (locals.kappaStore.length == 1) {
            //scalar logic separate to vector for efficiency
            locals.normalizationFactor /= int256(locals.prevWeightLength);
            // To avoid intermediate overflows (because of normalization), we only downcast in the end to an uint6
            // κ · ( (EWMA_short - EWMA_long) / EWMA_long − ℓp(t))
            for (locals.i = 0; locals.i < locals.prevWeightLength; ) {
                int256 res = int256(_prevWeights[locals.i]) +
                    locals.kappaStore[0].mul(locals.newWeights[locals.i] - locals.normalizationFactor);
                newWeightsConverted[locals.i] = res;

                unchecked {
                    ++locals.i;
                }
            }
        } else {
            //vector logic separate to vector for efficiency
            for (locals.i = 0; locals.i < locals.kappaStore.length; ) {
                locals.sumKappa += locals.kappaStore[locals.i];
                unchecked {
                    ++locals.i;
                }
            }
            //CODEHAWKS INFO /s/361
            locals.normalizationFactor = locals.normalizationFactor.div(locals.sumKappa);
            // To avoid intermediate overflows (because of normalization), we only downcast in the end to an uint6
            for (locals.i = 0; locals.i < _prevWeights.length; ) {
                locals.res =
                    int256(_prevWeights[locals.i]) +
                    locals.kappaStore[locals.i].mul(locals.newWeights[locals.i] - locals.normalizationFactor);

                //CODEHAWKS M-05 remove preguard +ve weight requirement same for scalar 
                newWeightsConverted[locals.i] = locals.res;
                unchecked {
                    ++locals.i;
                }
            }
        }
        return newWeightsConverted;
    }

    /// @notice Set the initial intermediate values for the pool, in this case the moving averages
    /// @param _poolAddress the target pool address
    /// @param _initialValues the initial values of the pool
    /// @param _numberOfAssets the number of assets in the pool
    function _setInitialIntermediateValues(
        address _poolAddress,
        int256[] memory _initialValues,
        uint _numberOfAssets
    ) internal override {
        require(_initialValues.length == _numberOfAssets, "Invalid initial values");

        //to avoid incorrect access to base MathMovingAverage, we need to set the moving average here
        uint movingAverageLength = shortMovingAverages[_poolAddress].length;

        if (movingAverageLength == 0 || _initialValues.length == _numberOfAssets) {
            //should be during create pool
            shortMovingAverages[_poolAddress] = _quantAMMPack128Array(_initialValues);
        } else {
            revert("Invalid set moving avg");
        }
    }

    /// @notice Check if the rule requires the previous moving average
    /// @return 0 if it does not require the previous moving average, 1 if it does
    function _requiresPrevMovingAverage() internal pure override returns (uint16) {
        return REQUIRES_PREV_MAVG;
    }

    /// @notice Check if the given parameters are valid for the rule
    /// @dev If parameters are not valid, either reverts or returns false
    function validParameters(int256[][] calldata _parameters) external pure override returns (bool) {
        if (_parameters.length != 2) {
            return false;
        }

        // lambda has to be less that int128 max value
        int256[] memory shortLambda = _parameters[1];
        for (uint i; i < shortLambda.length; ) {
            if (shortLambda[i] > int256(type(int128).max)) {
                return false;
            }
            if (shortLambda[i] < int256(0)) {
                return false;
            }
            if (shortLambda[i] > int256(1e18)) {
                return false;
            }
            unchecked {
                ++i;
            }
        }
        int256[] memory kappa = _parameters[0];
        uint16 valid = uint16(kappa.length) > 0 ? 1 : 0;

        int256 sumKappa = 0;

        for (uint i; i < kappa.length; ) {
            if (kappa[i] == 0) {
                unchecked {
                    valid = 0;
                }
                break;
            }
            sumKappa += kappa[i];

            unchecked {
                ++i;
            }
        }

        //CODEHAWKS INFO /s/664 edge case were all kappas sum to 0 cannot be used due to division by 0
        if (sumKappa == 0) {
            return false;
        }

        return valid == 1;
    }
}

